async def list_embeddings(conn: DBTX) -> list[models.Embedding]:
    _rows = await conn.fetch(_LIST_EMBEDDINGS)
    return [models.Embedding(id=_r[0], v=_r[1], v_null=_r[2], v_arr=_r[3]) for _r in _rows]


async def mood_array_null_elems(conn: DBTX) -> list[models.Mood] | None:
    _row = await conn.fetchrow(_MOOD_ARRAY_NULL_ELEMS)
    if _row is None:
        return None
    return typing.cast(list[models.Mood], _sqlc_enum_array(models.Mood, _row[0], 1))


async def multirange_array(conn: DBTX) -> list[list[asyncpg.Range[int]]] | None:
    _row = await conn.fetchrow(_MULTIRANGE_ARRAY)
    if _row is None:
        return None
    return typing.cast(list[list[asyncpg.Range[int]]], _row[0])


async def nearest_embedding(conn: DBTX, v: str) -> NearestEmbeddingRow | None:
    _row = await conn.fetchrow(_NEAREST_EMBEDDING, v)
    if _row is None:
        return None
    return NearestEmbeddingRow(id=_row[0], dist=_row[1])


async def null_literals(conn: DBTX) -> NullLiteralsRow | None:
    _row = await conn.fetchrow(_NULL_LITERALS)
    if _row is None:
        return None
    return NullLiteralsRow(ni=_row[0], nm=None if _row[1] is None else models.Mood(_row[1]), nma=_sqlc_enum_array(models.Mood, _row[2], 1), nta=_row[3])


async def scalar_casts(conn: DBTX, arg: ScalarCastsParams) -> ScalarCastsRow | None:
    _row = await conn.fetchrow(_SCALAR_CASTS, arg.dollar_1, arg.dollar_2, arg.dollar_3, arg.dollar_4, arg.dollar_5)
    if _row is None:
        return None
    return ScalarCastsRow(i=_row[0], arr=_row[1], mood=models.Mood(_row[2]), moods=_sqlc_enum_array(models.Mood, _row[3], 1), u=_row[4])
